begin;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position)
values ($g0$modal_verbs$g0$, $g1$Модальні дієслова (Modal Verbs)$g1$, $g2$Модальні дієслова в теперішньому, майбутньому й минулому: уміння, дозвіл, прохання, обов'язок, порада, впевненість і припущення, критика минулих дій.$g2$, 5)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g3$th_hero$g3$, $g4$Модальні дієслова$g4$, $g5$elementary$g5$, $g6$hero$g6$, $g7${"title":"Modal Verbs","chips":["Англійська граматика","Модальні дієслова"],"lead":"Маленькі дієслова <b>can, must, should, might</b> не називають дію, а додають до неї ставлення: уміння, дозвіл, обов'язок, пораду чи впевненість.","diagramTitle":"Як будується речення","diagram":[{"role":"підмет","label":"She · You · They","tone":"neutral"},{"role":"модальне дієслово","label":"can · must · should","tone":"colour"},{"role":"дієслово без to","label":"swim · go · stay","tone":"noun"}],"diagramNote":"Subject + Modal + V"}$g7$::jsonb, null, 0
from public.topics where slug = $g8$modal_verbs$g8$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g9$th_1$g9$, $g10$Модальні дієслова: загальні правила$g10$, $g11$elementary$g11$, $g12$formula$g12$, $g13${"step":"Правила","kicker":"Базове розуміння","lead":"Модальні дієслова поводяться не як звичайні: у них немає <b>-s</b>, після них немає <b>to</b>, а питання й заперечення обходяться без <b>do</b>.","tiles":[{"role":"підмет","label":"She","tone":"neutral"},{"role":"модальне","label":"can","tone":"colour"},{"role":"дієслово","label":"swim","tone":"noun"}],"legend":[{"tone":"colour","label":"без -s у 3-й особі: she can (НЕ cans)"},{"tone":"noun","label":"без to: must go (НЕ must to go); виняток — ought to"}],"examples":[{"text":"She <b>can</b> swim.","plain":"She can swim.","note":"без -s"},{"text":"You <b>must go</b>.","plain":"You must go.","note":"без to"},{"text":"<b>Can</b> you help? / You <b>shouldn't</b> smoke.","plain":"Can you help? You shouldn't smoke.","note":"без do"}],"note":"Одне дієслово — кілька значень: <i>You <b>must</b> go</i> (обов'язок) / <i>You <b>must</b> be tired</i> (впевненість). Дивіться на контекст.","tabs":[{"title":"Три форми","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Після модального дієслова може стояти одна з трьох форм:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">Modal + V — might <b>go</b><br>Modal + be + V-ing — might <b>be going</b><br>Modal + have + V3 — might <b>have gone</b></div>"},{"title":"Замінники","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Модальні не мають інфінітива, -ing чи минулої форми, і два модальні поспіль неможливі. Тому є замінники:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">can → be able to<br>must → have to<br>may (дозвіл) → be allowed to</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><s>will can</s> → <i>will be able to</i></p>"}]}$g13$::jsonb, null, 1
from public.topics where slug = $g14$modal_verbs$g14$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g15$th_2$g15$, $g16$Уміння: can / be able to$g16$, $g17$elementary$g17$, $g18$formula$g18$, $g19${"step":"Уміння","kicker":"Зараз і в майбутньому","lead":"<b>Can</b> — уміння й можливість у теперішньому. Коли граматика вимагає інфінітива, -ing, перфекта чи майбутнього, вживаємо <b>be able to</b>.","tiles":[{"role":"теперішнє","label":"can","tone":"opinion"},{"role":"усі інші форми","label":"be able to","tone":"colour"}],"legend":[{"tone":"opinion","label":"She can speak three languages."},{"tone":"colour","label":"will be able to · have been able to · to be able to · being able to"}],"examples":[{"text":"After this course you <b>will be able to</b> speak Spanish.","plain":"After this course you will be able to speak Spanish.","note":"майбутнє, НЕ will can"},{"text":"I'd like <b>to be able to</b> swim.","plain":"I'd like to be able to swim.","note":"інфінітив"},{"text":"<b>Not being able to</b> swim is annoying.","plain":"Not being able to swim is annoying.","note":"-ing форма"},{"text":"I <b>haven't been able to</b> sleep recently.","plain":"I haven't been able to sleep recently.","note":"перфект"}]}$g19$::jsonb, null, 2
from public.topics where slug = $g20$modal_verbs$g20$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g21$th_3$g21$, $g22$Уміння в минулому: could / was able to / managed to$g22$, $g23$intermediate$g23$, $g24$formula$g24$, $g25${"step":"Уміння в минулому","kicker":"Загалом чи один раз","lead":"<b>Could</b> — загальне вміння в минулому. Для <b>одного конкретного успіху</b> — <i>was able to</i> або <i>managed to</i>.","tiles":[{"role":"загалом","label":"could","tone":"opinion"},{"role":"один раз вдалося","label":"was able to · managed to","tone":"age"},{"role":"не вдалося","label":"couldn't = wasn't able to","tone":"origin"}],"examples":[{"text":"When I was young, I <b>could</b> run very fast.","plain":"When I was young, I could run very fast.","note":"загальне вміння"},{"text":"Luckily, Mary <b>was able to</b> help us.","plain":"Luckily, Mary was able to help us.","note":"один випадок, НЕ could"},{"text":"The fire spread quickly, but everyone <b>managed to</b> escape.","plain":"The fire spread quickly, but everyone managed to escape.","note":"один успіх"}],"note":"У запереченні різниці немає: <i>They <b>couldn't / weren't able to</b> save the dog.</i> А з дієсловами сприйняття <i>could</i> вживається і для одного разу: <i>I <b>could</b> hear music.</i>"}$g25$::jsonb, null, 3
from public.topics where slug = $g26$modal_verbs$g26$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g27$th_4$g27$, $g28$Дозвіл і прохання: can / could / may / be allowed to$g28$, $g29$elementary$g29$, $g30$formula$g30$, $g31${"step":"Дозвіл і прохання","kicker":"Ступені ввічливості","lead":"Попросити дозволу чи про допомогу можна з різним ступенем ввічливості.","tiles":[{"role":"просто","label":"Can I…?","tone":"neutral"},{"role":"ввічливо","label":"Could I…?","tone":"size"},{"role":"формально","label":"May I…?","tone":"opinion"},{"role":"дуже формально","label":"Might I…?","tone":"material"}],"legend":[{"tone":"opinion","label":"попросити дозволу: Can / Could / May I borrow your pen?"},{"tone":"colour","label":"попросити когось: Can / Could / Would you pass the salt?"}],"examples":[{"text":"<b>Could</b> you pass the salt?","plain":"Could you pass the salt?","note":"НЕ May you…"},{"text":"You <b>can / may</b> go now.","plain":"You can go now.","note":"дати дозвіл"},{"text":"Students <b>aren't allowed to</b> use phones.","plain":"Students aren't allowed to use phones.","note":"заборона правилами"}],"note":"У минулому загальний дозвіл — <i>could</i>, а одна конкретна ситуація — <i>was allowed to</i>: <i>Yesterday we <b>were allowed to</b> leave early.</i>","tabs":[{"title":"Заборона","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Заборонити можна двома способами:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">You <b>can't</b> park here.<br>You <b>aren't allowed to</b> park here.</div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>be allowed to</b> — дозвіл від правил чи інших людей, у будь-якому часі.</p>"}]}$g31$::jsonb, null, 4
from public.topics where slug = $g32$modal_verbs$g32$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g33$th_5$g33$, $g34$Пропозиції: shall / could / would you like$g34$, $g35$elementary$g35$, $g36$cases$g36$, $g37${"step":"Пропозиції","kicker":"Запропонувати й запросити","lead":"<b>Shall</b> у сучасній англійській живе переважно в питаннях-пропозиціях з <b>I</b> і <b>we</b>. Поруч із ним — інші ввічливі способи щось запропонувати.","cards":[{"icon":"↗","title":"Shall I…?","text":"Пропоную допомогу: мені зробити?","example":"It's cold. <b>Shall I</b> close the window?","examplePlain":"It's cold. Shall I close the window?"},{"icon":"⇄","title":"Shall we…?","text":"Пропоную зробити щось разом: може, підемо?","example":"<b>Shall we</b> go to the cinema tonight?","examplePlain":"Shall we go to the cinema tonight?"},{"icon":"◐","title":"could","text":"М'яка ідея, один із варіантів.","example":"If you're bored, you <b>could</b> read a book.","examplePlain":"If you're bored, you could read a book."},{"icon":"◎","title":"Would you like…?","text":"Запрошення, пропозиція. У ввічливій ситуації — замість Do you want.","example":"<b>Would you like</b> some tea?","examplePlain":"Would you like some tea?"},{"icon":"…","title":"Would you mind + -ing?","text":"Дуже ввічливе прохання.","example":"Would you mind <b>opening</b> the door?","examplePlain":"Would you mind opening the door?"}]}$g37$::jsonb, null, 5
from public.topics where slug = $g38$modal_verbs$g38$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
