insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g39$th_6$g39$, $g40$Обов'язок: must чи have to?$g40$, $g41$elementary$g41$, $g42$formula$g42$, $g43${"step":"Must чи have to","kicker":"Звідки обов'язок","lead":"У ствердженні обидва означають «треба», але джерело обов'язку різне.","tiles":[{"role":"так вважає мовець","label":"must","tone":"opinion"},{"role":"правила, обставини","label":"have to","tone":"colour"}],"legend":[{"tone":"opinion","label":"You must start working harder! — я так кажу"},{"tone":"colour","label":"You have to turn left here. — таке правило"}],"examples":[{"text":"Sorry, I <b>must leave / have to leave</b> now.","plain":"Sorry, I must leave now.","note":"часто різниці немає"},{"text":"Sorry I'm late, I <b>had to</b> take the children to school.","plain":"Sorry I'm late, I had to take the children to school.","note":"минуле — тільки had to"},{"text":"You'll <b>have to</b> wait.","plain":"You'll have to wait.","note":"майбутнє"}],"note":"<b>Must</b> не має минулої форми. Питання в минулому: <i><b>Did</b> you <b>have to</b> work late yesterday?</i>"}$g43$::jsonb, null, 6
from public.topics where slug = $g44$modal_verbs$g44$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
