insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g45$th_7$g45$, $g46$Mustn't ≠ don't have to / needn't$g46$, $g47$intermediate$g47$, $g48$formula$g48$, $g49${"step":"Mustn't чи don't have to","kicker":"Пастка заперечення","lead":"У ствердженні must і have to близькі, а в запереченні — <b>протилежні</b> за змістом.","tiles":[{"role":"не можна","label":"mustn't","tone":"origin"},{"role":"не обов'язково","label":"don't have to · needn't","tone":"age"}],"legend":[{"tone":"origin","label":"You mustn't leave now. — це проти правил"},{"tone":"age","label":"You don't have to leave now. — як хочеш"}],"examples":[{"text":"You <b>needn't</b> bring any food.","plain":"You needn't bring any food.","note":"needn't + V без to"},{"text":"Do I <b>need to</b> bring anything?","plain":"Do I need to bring anything?","note":"need to — з do"},{"text":"She <b>doesn't need to</b> worry.","plain":"She doesn't need to worry.","note":"після doesn't need — to"}],"note":"<b>Типові помилки:</b> <s>Need I to bring…?</s>, <s>She doesn't need worry.</s>"}$g49$::jsonb, null, 7
