insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g51$th_8$g51$, $g52$Порада: should / ought to / had better$g52$, $g53$intermediate$g53$, $g54$formula$g54$, $g55${"step":"Порада","kicker":"Найкраще було б","lead":"<b>Should</b> і <b>ought to</b> — порада, думка, ввічлива інструкція. <b>Had better</b> — сильна порада, щоб уникнути проблем.","tiles":[{"role":"порада","label":"should","tone":"opinion"},{"role":"порада","label":"ought to","tone":"size"},{"role":"інакше будуть проблеми","label":"had better","tone":"colour"}],"legend":[{"tone":"opinion","label":"should + V"},{"tone":"size","label":"ought to + V · ought not to + V"},{"tone":"colour","label":"had ('d) better (not) + V"}],"examples":[{"text":"I think you <b>should</b> see a doctor.","plain":"I think you should see a doctor."},{"text":"You <b>ought not to</b> smoke if you're pregnant.","plain":"You ought not to smoke if you're pregnant."},{"text":"I think you<b>'d better</b> leave now.","plain":"I think you'd better leave now.","note":"поки не пізно"},{"text":"You<b>'d better not</b> drive.","plain":"You'd better not drive.","note":"НЕ hadn't better"}],"note":"Попри форму <i>had</i>, <b>had better</b> стосується теперішнього й майбутнього, а після нього — інфінітив без to.","tabs":[{"title":"Should в інструкціях","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">У розмові should слабше за must і have to, але в офіційних текстах може звучати як розпорядження:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">Passengers <b>should</b> change at Reading.</div>"}]}$g55$::jsonb, null, 8
