insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g57$th_10$g57$, $g58$Впевненість у теперішньому: must / can't$g58$, $g59$intermediate$g59$, $g60$formula$g60$, $g61${"step":"Must be / can't be","kicker":"Логічний висновок","lead":"Must і can't також виражають <b>логічний висновок</b> — коли ми майже впевнені на підставі фактів. Особливо часто з дієсловом <i>be</i>.","tiles":[{"role":"напевно так ≈ 95%","label":"must","tone":"age"},{"role":"точно не так ≈ 0%","label":"can't","tone":"origin"}],"examples":[{"text":"You <b>must be</b> tired after your long journey.","plain":"You must be tired after your long journey.","note":"я впевнений, що так"},{"text":"That <b>can't be</b> Sue. She's in Brazil.","plain":"That can't be Sue. She's in Brazil.","note":"це неможливо"},{"text":"It's 5 o'clock already. Your watch <b>can't be</b> right.","plain":"It's 5 o'clock already. Your watch can't be right."}],"note":"<b>Типова помилка:</b> протилежність must у цьому значенні — can't, а не mustn't: <s>That mustn't be Sue.</s> → <i>That can't be Sue.</i>"}$g61$::jsonb, null, 9
