insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g63$th_11$g63$, $g64$Шкала ймовірності: may / might / could, should, be bound to$g64$, $g65$intermediate$g65$, $g66$formula$g66$, $g67${"step":"Шкала ймовірності","kicker":"Наскільки ймовірно","lead":"<b>May, might, could</b> — приблизно 50%, «можливо». Якщо наголосити модальне дієслово голосом, ймовірність ще менша. Інші модальні стоять на шкалі вище чи нижче.","tiles":[{"role":"0%","label":"can't","tone":"origin"},{"role":"≈ 50%","label":"may · might · could","tone":"colour"},{"role":"очікую","label":"should","tone":"size"},{"role":"≈ 100%","label":"must · be bound to","tone":"age"}],"examples":[{"text":"I <b>might</b> go out, I don't know. I <b>could</b> get wet!","plain":"I might go out, I don't know. I could get wet!","note":"можливо"},{"text":"Brenda <b>should be</b> home by now.","plain":"Brenda should be home by now.","note":"очікую, що так"},{"text":"You<b>'re bound to see</b> Paula if you go there.","plain":"You're bound to see Paula if you go there.","note":"точно станеться"},{"text":"Mind out! You <b>could</b> drop it!","plain":"Mind out! You could drop it!","note":"небезпека, НЕ can drop"}],"note":"Заперечення можливості — <i>might not / may not</i>, але НЕ <s>could not</s>: <i>She <b>might not</b> know.</i>"}$g67$::jsonb, null, 10
