insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g69$th_12$g69$, $g70$Висновки про минуле: must have / can't have / might have$g70$, $g71$advanced$g71$, $g72$formula$g72$, $g73${"step":"Must have / might have","kicker":"Висновки про минуле","lead":"Щоб зробити висновок про те, що <b>вже сталося</b>, додаємо <i>have + V3</i>.","tiles":[{"role":"модальне","label":"must · can't · might","tone":"colour"},{"role":"незмінне","label":"have","tone":"neutral"},{"role":"дієприкметник","label":"V3","tone":"noun"}],"legend":[{"tone":"age","label":"must have — впевнений, що так"},{"tone":"origin","label":"can't / couldn't have — впевнений, що ні"},{"tone":"colour","label":"may / might / could have — можливо"}],"examples":[{"text":"I <b>must have left</b> my wallet in the car.","plain":"I must have left my wallet in the car.","note":"впевнений"},{"text":"Jim <b>can't have noticed</b> you.","plain":"Jim can't have noticed you.","note":"точно ні"},{"text":"Jean <b>might have missed</b> the train.","plain":"Jean might have missed the train.","note":"можливо"},{"text":"You <b>could have been</b> killed!","plain":"You could have been killed!","note":"було можливо, але не сталося"}],"note":"<b>Не можна:</b> <s>must not have</s> для неможливості, <s>can have</s> для можливості, <s>could not have</s> у значенні «можливо, не». Тут потрібне <i>might not / may not have</i>: <i>Tim <b>might not have got</b> your letter.</i>"}$g73$::jsonb, null, 11
