insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g75$th_13$g75$, $g76$Критика і втрачені можливості: should have / could have$g76$, $g77$advanced$g77$, $g78$formula$g78$, $g79${"step":"Should have","kicker":"Докір і жаль","lead":"<b>Should have / ought to have + V3</b> — дорікаємо собі чи комусь: правильну дію не зробили, або зробили неправильну.","tiles":[{"role":"треба було, але не зробив","label":"should have done","tone":"opinion"},{"role":"не треба було, але зробив","label":"shouldn't have done","tone":"origin"},{"role":"була можливість","label":"could have done","tone":"size"}],"examples":[{"text":"I <b>should have posted</b> this letter yesterday.","plain":"I should have posted this letter yesterday.","note":"не зробив, і це погано"},{"text":"You <b>shouldn't have told</b> me the answer.","plain":"You shouldn't have told me the answer.","note":"даремно сказав"},{"text":"You <b>ought to have</b> known better.","plain":"You ought to have known better."},{"text":"You <b>could have phoned</b> from the station. Why didn't you?","plain":"You could have phoned from the station. Why didn't you?","note":"не скористався"}],"note":"У розмові <i>have</i> скорочується: <i>shouldn't've</i>, але на письмі так не пишемо."}$g79$::jsonb, null, 12
