insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g81$th_14$g81$, $g82$Минула необхідність: had to / needn't have / didn't need to$g82$, $g83$advanced$g83$, $g84$formula$g84$, $g85${"step":"Needn't have","kicker":"Чи зробили насправді","lead":"Дві схожі форми розрізняє одне питання: <b>чи зробили дію насправді?</b>","tiles":[{"role":"зробив, але даремно","label":"needn't have + V3","tone":"colour"},{"role":"не робив, не було потреби","label":"didn't need to + V","tone":"size"},{"role":"довелося","label":"had to + V","tone":"opinion"}],"examples":[{"text":"I <b>needn't have bought</b> a ticket.","plain":"I needn't have bought a ticket.","note":"купив, а виявилося — не треба"},{"text":"I <b>didn't need to buy</b> a ticket.","plain":"I didn't need to buy a ticket.","note":"не купував, знав, що не треба"},{"text":"We <b>needn't have worn</b> our raincoats.","plain":"We needn't have worn our raincoats.","note":"вдягли, а дощу не було"},{"text":"I <b>had to</b> go to London.","plain":"I had to go to London.","note":"must → had to"}],"note":"У побутовій мові <i>didn't need to</i> часто вживають в обох значеннях."}$g85$::jsonb, null, 13
