insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g87$th_18$g87$, $g88$Стоп-калька: модальні дієслова$g88$, $g89$elementary$g89$, $g90$traps$g90$, $g91${"step":"Стоп-калька","kicker":"Типові помилки","lead":"Більшість помилок — спроба поводитися з модальним дієсловом як зі звичайним: додати <b>-s</b>, <b>to</b> чи <b>do</b>.","items":[{"title":"«Вона вміє плавати»","bad":"She cans swim.","good":"She <b>can</b> swim.","goodPlain":"She can swim.","rule":"У модальних дієсловах немає -s у 3-й особі."},{"title":"«Ти мусиш іти»","bad":"You must to go.","good":"You <b>must go</b>.","goodPlain":"You must go.","rule":"Після модального — інфінітив без to. Виняток — <i>ought to</i>."},{"title":"«Ти можеш мені допомогти?»","bad":"Do you can help me?","good":"<b>Can</b> you help me?","goodPlain":"Can you help me?","rule":"Питання з модальним дієсловом — без do."},{"title":"«Я зможу прийти»","bad":"I will can come.","good":"I will <b>be able to</b> come.","goodPlain":"I will be able to come.","rule":"Два модальні поспіль неможливі — допомагає замінник <i>be able to</i>."},{"title":"«Тобі краще піти»","bad":"You had better to leave.","good":"You<b>'d better</b> leave.","goodPlain":"You'd better leave.","rule":"Після <i>had better</i> — інфінітив без to."},{"title":"«Учора я мусив сидіти вдома»","bad":"Yesterday I must stay at home.","good":"Yesterday I <b>had to</b> stay at home.","goodPlain":"Yesterday I had to stay at home.","rule":"<i>Must</i> не має минулої форми — <i>had to</i>."}]}$g91$::jsonb, null, 14
