insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g93$th_16$g93$, $g94$Would для минулих звичок (порівняно з used to)$g94$, $g95$intermediate$g95$, $g96$prose$g96$, null, $g97$
        <p class="text-slate-600 mb-3"><strong>Would</strong> описує дії, які <strong>регулярно повторювалися</strong> в минулому, — часто в спогадах.</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          <strong>would + V</strong> = повторювані дії &nbsp;|&nbsp; <strong>used to + V</strong> = і дії, і стани
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em>When I was little, my grandmother <strong>would tell</strong> me stories every evening.</em></li>
          <li>• <em>When she was young, the scientist <strong>would</strong> often <strong>spend</strong> all night working.</em></li>
          <li>• Для СТАНІВ (live, have, be, like, know) — тільки used to: <em>I <strong>used to live</strong> in Odesa.</em> (НЕ <s>would live</s>)</li>
          <li>• <em>We <strong>used to have</strong> a dog.</em> (НЕ <s>would have a dog</s>)</li>
        </ul>
      $g97$, 15
from public.topics where slug = $g98$modal_verbs$g98$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g99$th_17$g99$, $g100$Модальні в непрямій мові$g100$, $g101$intermediate$g101$, $g102$prose$g102$, null, $g103$
        <p class="text-slate-600 mb-3">У непрямій мові частина модальних змінюється, частина — ні.</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          can → could · may → might · will → would · shall → should · must → must / had to
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em>'You must go.'</em> → <em>He told me I <strong>must go</strong>. / He told me I <strong>had to go</strong>.</em></li>
          <li>• <em>'Shall I help?'</em> → <em>He asked if he <strong>should help</strong>.</em></li>
          <li>• <em>'You can use my car.'</em> → <em>She said I <strong>could</strong> use her car.</em></li>
          <li>• Could, would, should, might, ought to не змінюються.</li>
        </ul>
      $g103$, 16
from public.topics where slug = $g104$modal_verbs$g104$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g105$th_9$g105$, $g106$Правила й домовленості: be to / be supposed to$g106$, $g107$advanced$g107$, $g108$prose$g108$, null, $g109$
        <p class="text-slate-600 mb-3">Дві конструкції для того, що <strong>заплановано чи встановлено</strong> — але з різним відтінком.</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          <strong>be to</strong> = офіційна вказівка, розпорядження &nbsp;|&nbsp; <strong>be supposed to</strong> = так має бути (але часто не так) / так кажуть
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em>No-one <strong>is to</strong> leave the room. / You <strong>are not to</strong> leave the room.</em> — формальна інструкція (not наголошене)</li>
          <li>• <em>The train <strong>is supposed to</strong> arrive at 6, but it's always late.</em></li>
          <li>• <em>You <strong>aren't supposed to</strong> park here.</em> — правила забороняють</li>
          <li>• <em>This restaurant <strong>is supposed to</strong> be excellent.</em> — кажуть, що…</li>
          <li>• <strong>was/were to have + V3</strong> — мало статися, але не сталося (формально): <em>He <strong>was to have left</strong> yesterday.</em></li>
        </ul>
      $g109$, 17
from public.topics where slug = $g110$modal_verbs$g110$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g111$th_15$g111$, $g112$Модальні + тривалі форми: might be doing / must have been doing$g112$, $g113$advanced$g113$, $g114$prose$g114$, null, $g115$
        <p class="text-slate-600 mb-3">Коли припускаємо, що дія <strong>триває зараз</strong> або <strong>тривала в минулому</strong>, після модального ставимо тривалу форму.</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          <strong>Зараз:</strong> modal + be + V-ing &nbsp;|&nbsp; <strong>У минулому:</strong> modal + have been + V-ing
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em>Don't call her now — she <strong>might be sleeping</strong>.</em></li>
          <li>• <em>Listen! Someone <strong>must be knocking</strong> at the door.</em></li>
          <li>• <em>His eyes are red. He <strong>must have been crying</strong>.</em></li>
          <li>• <em>'Harriet wasn't in the meeting.' 'She <strong>might have been working</strong> in the lab.'</em></li>
          <li>• <em>You <strong>shouldn't have been driving</strong> so fast!</em></li>
        </ul>
      $g115$, 18
from public.topics where slug = $g116$modal_verbs$g116$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

